import{c as t,Q as a,j as o,m as s}from"./chunks/framework.rWdQudnF.js";const h=JSON.parse('{"title":"文件管理基础","description":"","frontmatter":{"title":"文件管理基础"},"headers":[],"relativePath":"综合知识/系统基础/操作系统/文件管理基础.md","filePath":"综合知识/系统基础/操作系统/文件管理基础.md","lastUpdated":null}'),i={name:"综合知识/系统基础/操作系统/文件管理基础.md"};function r(e,l,d,c,n,p){return a(),o("div",null,[...l[0]||(l[0]=[s('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[ ] 文件逻辑结构与物理结构</li><li>[ ] 存取方法（顺序/随机）</li><li>[ ] 文件属性（R/A/S/H）</li><li>[ ] 存取控制与硬链接</li><li>[ ] 链式存储与成组分解</li><li>[ ] 位示图</li><li>[ ] 文件存储空间管理</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="文件概述" tabindex="-1">文件概述 <a class="header-anchor" href="#文件概述" aria-label="Permalink to &quot;文件概述&quot;">​</a></h3><p>文件的逻辑结构：有结构的记录式文件、无结构的流式文件。</p><p>文件的物理结构（在物理存储设备上的存放方法）：</p><table tabindex="0"><thead><tr><th>结构</th><th>特点</th></tr></thead><tbody><tr><td>连续结构</td><td>逻辑连续的文件信息依次存放在连续物理块上</td></tr><tr><td>链接结构</td><td>存放在不连续物理块，每块有指针指向下一块</td></tr><tr><td>索引结构</td><td>存放在不连续物理块，系统建立索引表记录逻辑块号→物理块号映射</td></tr><tr><td>多级索引</td><td>索引表占用一个或多个物理块</td></tr></tbody></table><blockquote><p>⚠️ 文件物理结构<strong>不包括散列结构</strong>。连续结构支持快速随机访问但<strong>易产生碎片</strong>。</p></blockquote><p>存取方法：顺序存取、随机存取。</p><blockquote><p>⚠️ 顺序存取的效率<strong>不一定</strong>高于随机存取，取决于实际场景。文件可同时支持两种存取方式。</p></blockquote><h3 id="索引文件结构" tabindex="-1">索引文件结构 <a class="header-anchor" href="#索引文件结构" aria-label="Permalink to &quot;索引文件结构&quot;">​</a></h3><p>详见：<a href="/arch-exam/综合知识/系统基础/操作系统/索引文件结构.html">架构师-备考 综合知识-系统基础-操作系统-索引文件结构</a></p><h3 id="文件目录" tabindex="-1">文件目录 <a class="header-anchor" href="#文件目录" aria-label="Permalink to &quot;文件目录&quot;">​</a></h3><p>详见：<a href="/arch-exam/综合知识/系统基础/操作系统/文件目录.html">架构师-备考 综合知识-系统基础-操作系统-文件目录</a></p><h3 id="文件属性" tabindex="-1">文件属性 <a class="header-anchor" href="#文件属性" aria-label="Permalink to &quot;文件属性&quot;">​</a></h3><blockquote><p>🎯 一句话结论：R=只读、A=归档、S=系统文件、H=隐藏。</p></blockquote><table tabindex="0"><thead><tr><th>属性</th><th>含义</th></tr></thead><tbody><tr><td><strong>R</strong></td><td>只读文件</td></tr><tr><td><strong>A</strong></td><td>归档文件</td></tr><tr><td><strong>S</strong></td><td>系统文件</td></tr><tr><td><strong>H</strong></td><td>隐藏文件</td></tr></tbody></table><h3 id="存取控制与硬链接" tabindex="-1">存取控制与硬链接 <a class="header-anchor" href="#存取控制与硬链接" aria-label="Permalink to &quot;存取控制与硬链接&quot;">​</a></h3><blockquote><p>🎯 一句话结论：密码保护<strong>不属于</strong>存取控制类型。硬链接指向<strong>同一个 inode</strong>。</p></blockquote><p><strong>存取控制类型</strong>：存取控制矩阵、存取控制表、用户权限表。⚠️ <strong>密码保护</strong>不属于存取控制类型（属于密码保护类型）。</p><p><strong>硬链接</strong>：两个文件目录项指向<strong>同一个索引节点</strong>（inode），不是创建新文件实体，必须位于同一文件系统。</p><h3 id="链式存储与成组分解" tabindex="-1">链式存储与成组分解 <a class="header-anchor" href="#链式存储与成组分解" aria-label="Permalink to &quot;链式存储与成组分解&quot;">​</a></h3><blockquote><p>🎯 一句话结论：成组分解 = 多记录打包存入一块；读取时先读块再分解出目标记录。</p></blockquote><p>链式存储中，物理块不连续，每块有指针指向下一块。<strong>成组分解技术</strong>：多个逻辑记录打包存入一个物理块；读取时先将物理块读入缓冲区，再分解出目标记录。</p><blockquote><p>计算：磁盘块 4096 字节，记录 2048 字节 → 每块存 2 个记录。访问第 12288 字节 → 12288 / 4096 = <strong>第 3 个磁盘块</strong>（从 0 计数）。</p></blockquote><h3 id="位示图" tabindex="-1">位示图 <a class="header-anchor" href="#位示图" aria-label="Permalink to &quot;位示图&quot;">​</a></h3><blockquote><p>🎯 一句话结论：位示图每一位对应一个物理块，1 = 已占用，0 = 空闲。用于管理磁盘空闲块。</p></blockquote><h3 id="文件存储空间管理" tabindex="-1">文件存储空间管理 <a class="header-anchor" href="#文件存储空间管理" aria-label="Permalink to &quot;文件存储空间管理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方法</th><th>原理</th></tr></thead><tbody><tr><td>空闲区表</td><td>为每个连续空闲区建立表项，适用于连续文件结构</td></tr><tr><td>位示图 (Bitmap)</td><td>每一位对应一个物理块，0=空闲，1=占用</td></tr><tr><td>空闲块链</td><td>每个空闲块指向下一个空闲块，链表头指针放在特定位置</td></tr><tr><td>成组链接法</td><td>空闲块分组（如 100 块/组），每组第一块登记下一组盘块号和空闲块总数</td></tr></tbody></table><blockquote><p><strong>位示图计算</strong>：物理块号 N 在第 <code>⌊N/字长⌋</code> 个字中描述（从 0 编号即为第 <code>⌊N/字长⌋</code> 个字）。磁盘容量/物理块大小 = 物理块总数 → 除以字长 = 位示图所需字数。</p></blockquote><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><p><strong>[Q20] 链式存储+成组分解</strong></p><p>某文件系统采用链式存储管理方式并应用记录的成组与分解技术，且磁盘块的大小为 4096 字节。若文件 license.doc 由 7 个逻辑记录组成，每个逻辑记录的大小为 2048字节，并依次存放在 58、89、96 和 101 号磁盘块上，那么要存取文件的第 12288 逻辑字节处的信息，应访问（ ）号磁盘块。</p><ul><li>A. 58</li><li>B. 89</li><li>C. 96</li><li>D. 101</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：每块存2个记录(4096/2048=2)。12288/4096=3，第3块(从0计)→101号块。</p></div></details><hr><p><strong>[Q49] 位示图</strong></p><p>文件系统中，位示图（Bitmap）的作用是（ ）。</p><ul><li>A. 记录文件的创建时间</li><li>B. 索引文件内容</li><li>C. 存储文件的访问权限</li><li>D. 管理磁盘空闲块</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：位示图每一位对应一个物理块，标记占用/空闲，用于管理磁盘空闲空间。</p></div></details><hr><p><strong>[Q52] 物理结构类型</strong></p><p>在文件系统中，用于表示文件物理结构的类型不包括（ ）。</p><ul><li>A. 连续结构</li><li>B. 链接结构</li><li>C. 索引结构</li><li>D. 散列结构</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：文件物理结构三种：连续、链接、索引。散列/哈希不是文件物理结构。</p></div></details><hr><p><strong>[Q57] 连续结构</strong></p><p>（ ）文件组织方式支持快速随机访问但易产生碎片。</p><ul><li>A. 连续结构</li><li>B. 链接结构</li><li>C. 索引结构</li><li>D. 哈希结构</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：A</p><p>解析：连续结构=文件块连续存放→随机访问快；但增删文件易产生外碎片。</p></div></details><hr><p><strong>[Q59] 文件属性</strong></p><p>在文件管理系统中，以下哪个文件属性表示该文件是一个系统文件（ ）。</p><ul><li>A. R</li><li>B. A</li><li>C. S</li><li>D. H</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：R=只读(Read-only)，A=归档(Archive)，S=系统(System)，H=隐藏(Hidden)。</p></div></details><hr><p><strong>[Q84] 存取控制</strong></p><p>下列哪种文件保护方式不属于存取控制类型（ ）。</p><ul><li>A. 存取控制矩阵</li><li>B. 存取控制表</li><li>C. 用户权限表</li><li>D. 密码保护</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：密码保护属于加密保护，不是存取控制。存取控制=矩阵/ACL/权限表。</p></div></details><hr><p><strong>[Q85] 硬链接</strong></p><p>关于文件的硬链接，下列描述正确的是（ ）。</p><ul><li>A. 创建新的文件实体</li><li>B. 两个文件目录项指向同一个索引节点</li><li>C. 建立文件路径的映射关系</li><li>D. 必须位于同一个文件系统</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：B</p><p>解析：硬链接=多个目录项指向同一inode，不创建新实体，共享同一索引节点。</p></div></details><hr><p><strong>[Q86] 存取方法</strong></p><p>关于文件的存取方法，下列说法错误的是（ ）。</p><ul><li>A. 顺序存取是按顺序依次进行读写</li><li>B. 随机存取可以按任意次序读写</li><li>C. 顺序存取的效率总是高于随机存取</li><li>D. 文件可以同时支持两种存取方式</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：顺序存取不一定总比随机快。对于索引结构/直接访问场景，随机存取可能更快。</p></div></details><hr><p><strong>[Q87] 位示图取值</strong></p><p>在位示图法中，每一位对应一个物理块，当某位取值为1时表示（ ）。</p><ul><li>A. 该物理块空闲</li><li>B. 该物理块已占用</li><li>C. 该物理块损坏</li><li>D. 该物理块未初始化</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：B</p><p>解析：位示图中 1=已占用，0=空闲。</p></div></details><hr><p><strong>[Q88] 连续结构</strong></p><p>关于文件的连续结构（顺序结构），下列说法正确的是（ ）。</p><ul><li>A. 文件信息存放在不连续的物理块上</li><li>B. 每个物理块需要指针指向下一块</li><li>C. 需要建立索引表</li><li>D. 文件信息存放在连续编号的物理块上</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：D</p><p>解析：连续结构=文件块在磁盘上连续编号存放，无需指针和索引。</p></div></details><hr><p><strong>[Q89] 逻辑结构</strong></p><p>关于文件的逻辑结构，下列说法错误的是（ ）。</p><ul><li>A. 分为记录式文件和流式文件</li><li>B. 用户只需知道文件名就可以存取文件</li><li>C. 用户必须知道文件在磁盘上的物理位置</li><li>D. 记录式文件是有结构的文件</li></ul><details class="callout callout-note"><summary class="callout-title"><span class="callout-icon">📝</span>答案与解析</summary><div class="callout-body"><p>答案：C</p><p>解析：逻辑结构对用户透明，用户只需文件名，不需要知道物理位置。</p></div></details>',85)])])}const m=t(i,[["render",r]]);export{h as __pageData,m as default};
